import axios from 'axios';
import {
    GET_LEGITIMATE_DOMAINS,
    GET_LEGITIMATE_DOMAINS_ALL,
    DELETE_LEGITIMATE_DOMAIN,
    ADD_LEGITIMATE_DOMAIN,
    PATCH_LEGITIMATE_DOMAIN,
    EXPORT_LEGITIMATE_DOMAIN_TO_MISP,
    RESET_EXPORT_LOADING,
    GET_LEGITIMATE_DOMAIN_STATISTICS,
} from "./types";
import { createMessage, returnErrors } from "./messages";
import { tokenConfig } from "./auth";
import { fetchAllPages } from "./paginationUtils";

// GET LEGITIMATE DOMAINS
export const getLegitimateDomains = (page = 1, pageSize = 100) => (dispatch, getState) => {
    const isAuthenticated = getState().auth.isAuthenticated;
    
    const endpoint = `/api/common/legitimate_domains/?page=${page}&page_size=${pageSize}`;
    
    const config = isAuthenticated ? tokenConfig(getState) : {
        headers: {
            'Content-Type': 'application/json'
        }
    };
    
    return axios.get(endpoint, config)
        .then(res => {
            dispatch({
                type: GET_LEGITIMATE_DOMAINS,
                payload: {
                    results: res.data.results || res.data,
                    count: res.data.count || (Array.isArray(res.data) ? res.data.length : 0),
                    next: res.data.next || null,
                    previous: res.data.previous || null
                }
            });
            return res.data;
        })
        .catch(err => {
            if (err.response) {
                dispatch(returnErrors(err.response.data, err.response.status));
            }
            dispatch({
                type: GET_LEGITIMATE_DOMAINS,
                payload: {
                    results: [],
                    count: 0,
                    next: null,
                    previous: null
                }
            });
            throw err;
        });
};


export const getLegitimateDomainsBatch = (startPage = 2, pageSize = 100) => async (dispatch, getState) => {
    const config = tokenConfig(getState);
    const allResults = [];
    let page = startPage;
    let hasMore = true;

    while (hasMore) {
        try {
            const res = await axios.get(
                `/api/common/legitimate_domains/?page=${page}&page_size=${pageSize}`,
                config
            );
            const data = res.data;
            allResults.push(...(data.results || []));
            hasMore = !!data.next;
            page++;
        } catch (_) {
            hasMore = false;
        }
    }

    if (allResults.length > 0) {
        dispatch({
            type: GET_LEGITIMATE_DOMAINS,
            payload: { results: allResults, count: allResults.length, next: null, previous: null },
        });
    }
};

// ADD LEGITIMATE DOMAIN
export const addLegitimateDomain = domain => (dispatch, getState) => {
    axios.post('/api/common/legitimate_domains/', domain, tokenConfig(getState))
        .then(res => {
            dispatch(createMessage({ add: `${domain.domain_name} Added` }));
            dispatch({
                type: ADD_LEGITIMATE_DOMAIN,
                payload: res.data
            });
            
            dispatch(getLegitimateDomains());
        })
        .catch(err =>
            dispatch(returnErrors(err.response.data, err.response.status))
        );
};

// PATCH LEGITIMATE DOMAIN
export const patchLegitimateDomain = (id, domain) => (dispatch, getState) => {
    axios.patch(`/api/common/legitimate_domains/${id}/`, domain, tokenConfig(getState))
        .then(res => {
            dispatch(createMessage({ add: `${domain.domain_name} Updated` }));
            dispatch({
                type: PATCH_LEGITIMATE_DOMAIN,
                payload: res.data
            });
            
            dispatch(getLegitimateDomains());
        })
        .catch(err =>
            dispatch(returnErrors(err.response.data, err.response.status))
        );
};

// DELETE LEGITIMATE DOMAIN
export const deleteLegitimateDomain = (id, domain_name) => (dispatch, getState) => {
    axios.delete(`/api/common/legitimate_domains/${id}/`, tokenConfig(getState))
        .then(res => {
            dispatch(createMessage({ delete: `${domain_name} Deleted` }));
            dispatch({
                type: DELETE_LEGITIMATE_DOMAIN,
                payload: id
            });
        })
        .catch(err =>
            dispatch(returnErrors(err.response.data, err.response.status))
        );
};

// EXPORT TO MISP
export const exportToMISP = (payload) => (dispatch, getState) => {
    axios
        .post('/api/common/legitimate_domains/misp/', payload, tokenConfig(getState))
        .then(res => {
            const message = res.data.message || "Legitimate Domain exported to MISP";
            
            dispatch(createMessage({ add: message }));
            
            if (res.data.misp_event_uuid) {
                dispatch({
                    type: EXPORT_LEGITIMATE_DOMAIN_TO_MISP,
                    payload: {
                        id: payload.id,
                        misp_event_uuid: res.data.misp_event_uuid,
                        message: message
                    }
                });
            }
            
            dispatch(getLegitimateDomains());
        })
        .catch(err => {
            const errorMsg = err.response?.data?.message || 'Failed to export to MISP';
            dispatch(returnErrors(err.response.data, err.response.status));
        })
        .finally(() => {
            dispatch({ 
                type: RESET_EXPORT_LOADING, 
                payload: payload.id 
            });
        });
};

// GET LEGITIMATE DOMAIN STATISTICS
export const getLegitimateDomainStatistics = () => (dispatch, getState) => {
    const endpoint = '/api/common/legitimate_domains/statistics/';
    
    const config = {
        headers: {
            'Content-Type': 'application/json'
        }
    };
    
    axios.get(endpoint, config)
        .then(res => {
            dispatch({
                type: GET_LEGITIMATE_DOMAIN_STATISTICS,
                payload: res.data
            });
        })
        .catch(err => {
            if (err.response) {
                dispatch(returnErrors(err.response.data, err.response.status));
            }
            dispatch({
                type: GET_LEGITIMATE_DOMAIN_STATISTICS,
                payload: {
                    total: 0,
                    repurchased: 0,
                    expired: 0,
                    expiringSoon: 0
                }
            });
        });
};
// GET ALL LEGITIMATE DOMAINS (stats only)
export const getAllLegitimateDomains = () => (dispatch, getState) => {
    return fetchAllPages('/api/common/legitimate_domains/', getState)
        .then(results => {
            dispatch({ type: GET_LEGITIMATE_DOMAINS_ALL, payload: results });
            return results;
        })
        .catch(err => {
            dispatch(returnErrors(err.response?.data, err.response?.status));
        });
};

// Bulk descriptor of this module (see actions/Bulk.js): the API base, the action that drops a removed row from the
// store (list reducers merge what the server returns) and what to reload afterwards (list + dashboard statistics).
export const LEGITIMATE_DOMAIN_BULK = {
    endpoint: "/api/common/legitimate_domains/",
    removedType: DELETE_LEGITIMATE_DOMAIN,
    refresh: [getLegitimateDomains, getAllLegitimateDomains, getLegitimateDomainStatistics],
};
